//////////////////////////////////////////////////////////
// Mercury Dreams
// by Doers DF (www.doersdf.com)
//////////////////////////////////////////////////////////

//-------------------------------
// CONFIGURACIÓN
//-------------------------------
#define NUM_SPHERES 20   // Número de esferas
const float SMOOTH_K  = 0.8; // Factor de suavizado en la unión
const float REFLECT_MIX = 0.9; // Mezcla con el "cromo" (0=solo color, 1=solo reflejo)
const vec3 SKY    = vec3(0.3, 0.2, .9); // Color superior
const vec3 GROUND = vec3(0.2, 0.9, 0.1); // Color inferior

//--------------------------------------------------------
// Estructura para devolver distancia y color desde el SDF
//--------------------------------------------------------
struct SdfRes {
    float d;   // distancia
    vec3  c;   // color
};

//--------------------------------------------------------
// Función auxiliar: hsl2rgb (para obtener colores degradados)
//--------------------------------------------------------
float hue2rgb(in float p, in float q, in float t)
{
    if(t < 0.0) t += 1.0;
    if(t > 1.0) t -= 1.0;
    if(t < 1.0/6.0) return p + (q - p) * 6.0 * t;
    if(t < 1.0/2.0) return q;
    if(t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
    return p;
}
vec3 hsl2rgb( vec3 hsl )
{
    // h,s,l en rangos [0,1]
    // Conversión sencilla a RGB
    float H = hsl.x;
    float S = hsl.y;
    float L = hsl.z;

    // Función auxiliar
    float f1 = L < 0.5 ? L * (1.0 + S) : L + S - L * S;
    float f2 = 2.0 * L - f1;



    float r = hue2rgb(f2, f1, H + 1.0/3.0);
    float g = hue2rgb(f2, f1, H);
    float b = hue2rgb(f2, f1, H - 1.0/3.0);

    return vec3(r, g, b);
}

//--------------------------------------------------------
// Smooth Union para SdfRes (fusiona tanto distancia como color)
//--------------------------------------------------------
SdfRes smoothUnion(SdfRes s1, SdfRes s2, float k)
{
    float h = clamp( 0.5 + 0.5*(s2.d - s1.d)/k, 0.0, 1.0 );
    float d = mix(s2.d, s1.d, h) - k * h * (1.0 - h);
    // Mezclamos colores según h
    vec3  c = mix(s2.c, s1.c, h);
    return SdfRes(d, c);
}

//--------------------------------------------------------
// SDF de esfera
//--------------------------------------------------------
float sdSphere(vec3 p, float r)
{
    return length(p) - r;
}

//--------------------------------------------------------
// Genera el color para la esfera i
//--------------------------------------------------------
vec3 getSphereColor(int i, float time)
{
    // Ejemplo: variamos el tono (H) en [0..1] según i
    // y añadimos un leve desplazamiento con el tiempo
    float fi  = float(i);
    float hue = fract( fi / float(NUM_SPHERES) + 0.1 * time );
    float sat = 0.9;  // saturación
    float lum = 0.5;  // luminosidad

    return hsl2rgb(vec3(hue, sat, lum));
}

//--------------------------------------------------------
// Función principal de la escena: combina esferas
//--------------------------------------------------------
SdfRes mapScene(vec3 p, float time)
{
    // Inicializamos con distancia grande y color negro
    SdfRes res = SdfRes(9999.0, vec3(0.0));

    for(int i = 0; i < NUM_SPHERES; i++)
    {
        float fi = float(i);

        // Ejemplo de "pseudo-posición" animada
        float rx = sin( fi*3.14 + time ) * 2.0;
        float rz = cos( fi*1.73 + time*1.1 ) * 2.0;

        // Centro de la esfera i
        vec3 center = vec3(rx, 0.5*sin(time + fi*0.5), rz);

        // Radio
        float r = 0.6;

        // Calculamos SDF de la esfera

        float d = sdSphere(p*0.5 - center, r);

        // Color asociado a esta esfera
        vec3 c = getSphereColor(i, time);

        // Creamos el SdfRes correspondiente
        SdfRes s2 = SdfRes(d, c);

        // Fusionamos con el acumulado
        res = smoothUnion(res, s2, SMOOTH_K);
    }

    return res;
}

//--------------------------------------------------------
// Cálculo de la normal (gradiente numérico)
//--------------------------------------------------------
vec3 calcNormal(vec3 p, float time)
{
    const float eps = 0.001;

    float d  = mapScene(p, time).d;
    float dx = mapScene(vec3(p.x+eps, p.y, p.z), time).d - d;
    float dy = mapScene(vec3(p.x, p.y+eps, p.z), time).d - d;
    float dz = mapScene(vec3(p.x, p.y, p.z+eps), time).d - d;

    return normalize(vec3(dx, dy, dz));
}

//--------------------------------------------------------
// Mapeo de entorno sencillo (cielo vs suelo)
//--------------------------------------------------------
vec3 envMap(vec3 dir)
{
    // Mezclamos cielo y suelo en función de Y
    float t = 0.5 * (dir.y + 1.0);


    return mix(GROUND, SKY, t);
}

//--------------------------------------------------------
// Ray Marching
//--------------------------------------------------------
vec4 raymarch(vec3 ro, vec3 rd, float time)
{
    const float MAX_DIST = 15.0;
    const int   MAX_STEP = 200;

    float totalDist = 2.0;

    for(int i = 0; i < MAX_STEP; i++)
    {
        vec3 pos = ro + rd*totalDist;

        // Obtenemos distancia y color según la escena
        SdfRes sres = mapScene(pos, time);

        if(sres.d < 0.001)
        {
            // Hemos chocado con la superficie
            // Calculamos normal
            vec3 normal = calcNormal(pos, time);
            // Reflexión tipo "cromo"
            vec3 reflDir = reflect(rd, normal);

            // Color base del material (mezcla entre la fusión SDF y el "envMap")
            // -- Se mezcla el color local con el color del entorno (efecto espejo)
            vec3 envColor = envMap(reflDir);

            // REFLECT_MIX cercano a 0 = casi todo color de la esfera
            // REFLECT_MIX cercano a 1 = casi todo reflejo "cromo"
            vec3 finalColor = mix(sres.c, envColor, REFLECT_MIX);

            // Añadimos un ligero factor difuso para resaltar la forma
            float diff = max(dot(normal, vec3(0.0, 1.0, 0.0)), 0.0);
            finalColor *= (0.5 + 0.5*diff);

            return vec4(finalColor, 1.0);
        }

        totalDist += sres.d;
        if(totalDist > MAX_DIST)
            break;
    }

    // Si no intersectamos nada, color de fondo (negro)
    return vec4(0.0, 0.0, 0.0, 1.0);
}

//--------------------------------------------------------
// Función principal Shadertoy
//--------------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Coordenadas normalizadas [-1..1]
    vec2 uv = (2.0*fragCoord - iResolution.xy) / iResolution.y;

    // Definimos la cámara
    vec3 ro = vec3(0.0, 0.0, 5.0);  // Origen
    vec3 ta = vec3(0.0, 0.0, 0.0);  // Punto de mira
    vec3 ww = normalize(ta - ro);
    vec3 uu = normalize(cross(vec3(0,1,0), ww));
    vec3 vv = cross(ww, uu);

    // Generamos el rayo
    vec3 rd = normalize(uv.x*uu + uv.y*vv + ww);

    // Tiempo
    float time = iTime;

    // Ray marching para obtener color final
    fragColor = raymarch(ro, rd, time);
}
